import threading

class SafeCounter:
    def __init__(self):
        self._lock = threading.Lock()
        self._value = 0

    def _validate_amount(self, n):
        if isinstance(n, bool) or not isinstance(n, int):
            raise ValueError("amount must be a non-bool integer")
        if n < 0:
            raise ValueError("amount must be >= 0")

    def increment(self, n=1):
        if isinstance(n, bool) or not isinstance(n, int):
            raise ValueError("n must be an integer")
        with self._lock:
            self._value += n

    def decrement(self, n=1):
        if isinstance(n, bool) or not isinstance(n, int):
            raise ValueError("n must be an integer")
        with self._lock:
            self._value -= n

    def value(self):
        with self._lock:
            return self._value

    def compare_and_set(self, expected, new):
        if isinstance(expected, bool) or not isinstance(expected, int):
            raise ValueError("expected must be an integer")
        if isinstance(new, bool) or not isinstance(new, int):
            raise ValueError("new must be an integer")
        with self._lock:
            if self._value == expected:
                self._value = new
                return True
            return False

    def transfer_to(self, other, n):
        self._validate_amount(n)
        if other is self:
            return
        first, second = (self, other) if id(self) < id(other) else (other, self)
        with first._lock:
            with second._lock:
                self._value -= n
                other._value += n

    def _order_key(self):
        return id(self)
